    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryValidatorBondFloorUpdated (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<ValidatorBondFloorUpdatedEvent>>()
        let event = contract.GetEventBySignature("0x2f7b35cc8d88e3120704c0f44a5bc87b374e00b3ac0dade1c97eb9585048c7aa")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<ValidatorBondFloorUpdatedEvent>(decodeValidatorBondFloorUpdatedEvent contract log, log))
        return result
    }

let decodeOutOfRangeError (data: string) : OutOfRangeError =
    if isNull data || not (data.StartsWith("0x7db3aba7", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<OutOfRangeError>).DecodeExceptionEncodedData<OutOfRangeError>(data)

